export type Flashcard = {
  id: string;
  track: 'robotica' | 'ai' | 'ambos';
  module: string;
  front: string;
  back: string;
  hint?: string;
};

export const flashcards: Flashcard[] = [
  // ---------- Electrónica (b1) ----------
  { id: 'fc-001', track: 'robotica', module: 'b1', front: '¿Qué establece la ley de Ohm?', back: 'El voltaje entre dos puntos es igual a la corriente por la resistencia: V = I·R. Es la relación básica para dimensionar resistores y predecir caídas de voltaje.', hint: 'Triángulo V-I-R' },
  { id: 'fc-002', track: 'robotica', module: 'b1', front: '¿Cómo se combinan resistencias en serie?', back: 'Se suman directamente: R_eq = R1 + R2 + ... . Por ellas circula la misma corriente y el voltaje se reparte proporcionalmente.' },
  { id: 'fc-003', track: 'robotica', module: 'b1', front: '¿Cómo se combinan resistencias en paralelo?', back: '1/R_eq = 1/R1 + 1/R2 + ... . La equivalente siempre es menor que la menor resistencia; dos resistencias iguales dan R/2.', hint: 'Piensa en más caminos para la corriente' },
  { id: 'fc-004', track: 'robotica', module: 'b1', front: '¿Qué dice la ley de corrientes de Kirchhoff (KCL)?', back: 'En un nodo, la suma de corrientes que entran iguala la suma de las que salen. Es conservación de carga: la corriente no se acumula en un punto.' },
  { id: 'fc-005', track: 'robotica', module: 'b1', front: '¿Qué dice la ley de voltajes de Kirchhoff (KVL)?', back: 'La suma algebraica de las diferencias de potencial alrededor de una malla cerrada es cero. Las subidas de voltaje compensan exactamente las caídas.', hint: 'Da una vuelta al circuito y vuelves al mismo punto' },
  { id: 'fc-006', track: 'robotica', module: 'b1', front: '¿Qué es un divisor de voltaje?', back: 'Dos resistencias en serie entre Vin y masa dan Vout = Vin·R2/(R1+R2), tomada sobre R2. Es la forma más simple de generar un voltaje de referencia.' },
  { id: 'fc-007', track: 'robotica', module: 'b1', front: '¿Cuál es la trampa principal de un divisor de voltaje?', back: 'Al conectar una carga, esta queda en paralelo con R2 y cambia la relación: el voltaje cae. Sirve para señales o referencias de alto impedancia, no para alimentar motores; usa un regulador o un buffer.', hint: '¿Qué pasa si pones un motor en Vout?' },
  { id: 'fc-008', track: 'robotica', module: 'b1', front: '¿Qué hace un capacitor?', back: 'Almacena carga (Q = C·V) y se opone a cambios bruscos de voltaje. En corriente continua se comporta como circuito abierto; en transitorios entrega o absorbe corriente.' },
  { id: 'fc-009', track: 'robotica', module: 'b1', front: '¿Para qué sirve un capacitor de desacople o bypass?', back: 'Se coloca cerca de los pines de alimentación del chip para filtrar ruido y suministrar picos de corriente. Lo habitual es combinar 100 nF cerámico con un electrolítico de 10 µF o más.' },
  { id: 'fc-010', track: 'robotica', module: 'b1', front: '¿Cómo se comporta un capacitor según la frecuencia?', back: 'Su impedancia es Z = 1/(2πfC): infinita en DC y muy baja en alta frecuencia. Por eso pasa ruido AC a masa pero no altera la continua.', hint: 'Cuanto mayor la frecuencia, menor la impedancia' },
  { id: 'fc-011', track: 'robotica', module: 'b1', front: '¿Qué hace un diodo?', back: 'Conduce cuando el ánodo está a mayor potencial que el cátodo y bloquea en sentido inverso. Actúa como válvula de una sola vía para la corriente.' },
  { id: 'fc-012', track: 'robotica', module: 'b1', front: '¿Qué caída de voltaje introduce un diodo?', back: 'Aproximadamente 0.7 V en silicio y 0.2-0.4 V en Schottky. Hay que descontarla en los cálculos; el modelo ideal de 0 V solo sirve como aproximación gruesa.' },
  { id: 'fc-013', track: 'robotica', module: 'b1', front: '¿Para qué sirve un diodo flyback o de rueda libre?', back: 'Cuando cortas la corriente de una bobina, el diodo da un camino a la corriente inductiva y evita un pico de voltaje invertido. Protege el transistor o el driver.', hint: 'Relé, motor o cualquier inductancia' },
  { id: 'fc-014', track: 'robotica', module: 'b1', front: '¿Qué es un transistor BJT y cómo se usa como interruptor?', back: 'Una pequeña corriente en la base controla una corriente mayor entre colector y emisor. Como interruptor se maneja en corte (apagado) o saturación (encendido), siempre con resistor en la base.' },
  { id: 'fc-015', track: 'robotica', module: 'b1', front: '¿Por qué se usa un MOSFET como interruptor?', back: 'La compuerta se controla por voltaje y consume casi corriente, y en conducción tiene una resistencia Rds(on) muy baja. Ideal para conmutar cargas de potencia con un GPIO.' },
  { id: 'fc-016', track: 'robotica', module: 'b1', front: '¿Qué diferencia un MOSFET de canal N de uno de canal P?', back: 'El de canal N se usa como interruptor de lado bajo (conmuta a masa) y suele tener menor Rds(on); el de canal P conmuta el lado alto (a Vcc). Para el lado alto con N hace falta un driver de gate o bootstrap.', hint: '¿Dónde pones el interruptor: arriba o abajo de la carga?' },
  { id: 'fc-017', track: 'robotica', module: 'b1', front: '¿Cuál es el voltaje nominal por celda de una batería LiPo?', back: '3.7 V nominal, 4.2 V completamente cargada y alrededor de 3.0-3.3 V descargada. El cargador balanceador vigila cada celda por separado.' },
  { id: 'fc-018', track: 'robotica', module: 'b1', front: '¿Qué significa una batería 3S 2200 mAh 25C?', back: '3 celdas en serie (11.1 V nominal, 12.6 V cargada), 2.2 Ah de capacidad y descarga continua de 25·2.2 = 55 A. La "C" indica corriente en múltiplos de la capacidad.' },
  { id: 'fc-019', track: 'robotica', module: 'b1', front: '¿Por qué es crítico no descargar demasiado una LiPo?', back: 'Bajar de unos 3.0 V por celda degrada la química y puede inflar la batería o provocar un incendio. Usa un BMS o un corte por bajo voltaje en el firmware.' },
  { id: 'fc-020', track: 'robotica', module: 'b1', front: '¿Cómo se mide corriente con un multímetro?', back: 'El multímetro va en serie con el circuito y las sondas en los puertos A o mA. Medir en paralelo crea un cortocircuito y suele quemar el fusible interno.', hint: 'El amperímetro se interrumpe para medir' },
  { id: 'fc-021', track: 'robotica', module: 'b1', front: '¿Qué diferencia el modo continuidad del modo resistencia?', back: 'Continuidad solo avisa con un beep si la resistencia está por debajo de un umbral bajo (~30-50 Ω); resistencia da el valor numérico. En ambos casos se mide con el circuito apagado.' },
  { id: 'fc-022', track: 'robotica', module: 'b1', front: '¿Cuáles son los errores de soldadura más frecuentes?', back: 'Puente de estaño entre pines, unión fría (aspecto opaco y granular) y sobrecalentamiento del componente. Punta limpia, flux y calor aplicado a la almohadilla suelen resolverlo.', hint: 'Una unión brillante y cónica es buena señal' },

  // ---------- Microcontroladores (b3) ----------
  { id: 'fc-023', track: 'robotica', module: 'b3', front: '¿Qué es un pin GPIO?', back: 'Una entrada/salida digital configurable por software. Según su modo lee o genera niveles 0 y Vcc (3.3 V en ESP32, 5 V en Arduino clásico).' },
  { id: 'fc-024', track: 'robotica', module: 'b3', front: '¿Para qué sirven las resistencias pull-up y pull-down?', back: 'Fijan un nivel conocido cuando nadie maneja la línea, evitando entradas flotantes. Un pull-up la lleva a Vcc y un pull-down a masa; el ESP32 tiene ambas internas.', hint: 'El botón suelta el pin: ¿qué valor lee?' },
  { id: 'fc-025', track: 'robotica', module: 'b3', front: '¿Qué es el debouncing de un pulsador?', back: 'Los contactos mecánicos rebota durante unos milisegundos y generan varios flancos. Se corrige con un retardo de 20-50 ms, muestreo periódico o un filtro RC/Schmitt.' },
  { id: 'fc-026', track: 'robotica', module: 'b3', front: '¿Qué es PWM?', back: 'Una señal digital de frecuencia fija cuyo ciclo de trabajo (duty) varía. El valor promedio es Vcc·duty, lo que permite simular una salida analógica con un pin digital.' },
  { id: 'fc-027', track: 'robotica', module: 'b3', front: '¿Cómo afecta el duty cycle a un LED o a un motor?', back: 'Duty = tiempo en alto / periodo. Al 50 % el LED brilla aproximadamente la mitad y el motor recibe la mitad de voltaje efectivo; al 100 % va a pleno.', hint: 'Es el tanto por ciento del periodo en alto' },
  { id: 'fc-028', track: 'robotica', module: 'b3', front: '¿Qué frecuencia de PWM conviene para cada aplicación?', back: 'Motores: ~20 kHz para salir del rango audible. LEDs: por encima de ~100 Hz para que no parpadee el ojo. Servos RC: 50 Hz con pulso de 1-2 ms.' },
  { id: 'fc-029', track: 'robotica', module: 'b3', front: '¿Qué hace un ADC y cuál es su resolución?', back: 'Convierte un voltaje analógico en un número entero. Con N bits hay 2^N niveles y 1 LSB = Vref/2^N; un ADC de 12 bits con 3.3 V da ~0.8 mV por nivel.' },
  { id: 'fc-030', track: 'robotica', module: 'b3', front: '¿Qué pasa si la fuente de una entrada ADC tiene alta impedancia?', back: 'La lectura se vuelve ruidosa o inexacta porque el capacitor de muestreo del ADC no llega a cargarse. Se usa un buffer, un capacitor cercano o promediado de muestras.' },
  { id: 'fc-031', track: 'robotica', module: 'b3', front: '¿Qué es una interrupción?', back: 'El hardware suspende el flujo normal y salta a una rutina de servicio (ISR) cuando ocurre un evento. Permite reaccionar a pulsos o flancos sin estar sondeando el pin en bucle.' },
  { id: 'fc-032', track: 'robotica', module: 'b3', front: '¿Por qué una ISR debe ser breve?', back: 'Mientras se ejecuta se bloquean otras interrupciones y el programa principal. Solo conviene marcar un flag o meter un dato en una cola; nada de delay, Serial o malloc dentro.', hint: 'Entra, toma nota y sal' },
  { id: 'fc-033', track: 'robotica', module: 'b3', front: '¿Qué es I2C?', back: 'Bus síncrono de dos hilos (SDA y SCL) con direcciones de 7 bits y roles maestro/esclavo. Velocidades típicas: 100 kHz, 400 kHz y 1 MHz en modo Fast+.', hint: 'Dos cables, muchos dispositivos' },
  { id: 'fc-034', track: 'robotica', module: 'b3', front: '¿Qué es SPI?', back: 'Bus síncrono de cuatro hilos: MOSI, MISO, SCK y CS. Es full-duplex y muy rápido, pero necesita una línea de selección por cada esclavo.' },
  { id: 'fc-035', track: 'robotica', module: 'b3', front: '¿Qué es UART?', back: 'Comunicación serie asíncrona con dos hilos (TX y RX) y un baud rate acordado. No usa reloj compartido y suele conectar dos dispositivos punto a punto.' },
  { id: 'fc-036', track: 'robotica', module: 'b3', front: '¿Qué diferencia I2C de SPI?', back: 'I2C ahorra pines y permite muchos dispositivos en el mismo par de hilos, pero es más lento. SPI es más rápido y full-duplex, pero gasta más pines y un CS por dispositivo.', hint: 'Compara número de hilos y velocidad' },
  { id: 'fc-037', track: 'robotica', module: 'b3', front: '¿Qué es el ESP32?', back: 'Un SoC de Espressif con WiFi, Bluetooth, doble núcleo en los modelos clásicos y periféricos GPIO, ADC, PWM, I2C y SPI. El ESP32-C3/C6 usan RISC-V y algunos tienen un solo núcleo.' },
  { id: 'fc-038', track: 'robotica', module: 'b3', front: '¿Qué es una actualización OTA?', back: 'Flashear firmware nuevo por WiFi sin cable USB. Requiere esquema de particiones dual y mecanismo de rollback para no dejar el dispositivo inutilizable si falla.', hint: 'Over-The-Air' },
  { id: 'fc-039', track: 'robotica', module: 'b3', front: '¿Qué es un RTOS?', back: 'Un sistema operativo de tiempo real con planificador determinista: tareas con prioridades, ticks y primitivas de sincronización. Permite separar lectura de sensores, control y comunicaciones.' },
  { id: 'fc-040', track: 'robotica', module: 'b3', front: '¿Qué es FreeRTOS en el ESP32?', back: 'Es el RTOS que trae ESP-IDF (y el Arduino-ESP32 por debajo). Se usan xTaskCreate, colas, semáforos y vTaskDelay para crear tareas concurrentes con prioridades.' },
  { id: 'fc-041', track: 'robotica', module: 'b3', front: '¿Qué es un watchdog timer (WDT)?', back: 'Un contador de hardware que reinicia el sistema si el software no lo "alimenta" a tiempo. Detecta bucles infinitos o tareas bloqueadas y recupera el dispositivo.', hint: 'Si el perro no come, muerde' },
  { id: 'fc-042', track: 'robotica', module: 'b3', front: '¿Cómo se evita que dos tareas accedan a la vez a un recurso compartido?', back: 'Con un mutex o un semáforo binario; el mutex además puede implementar herencia de prioridad para evitar inversiones de prioridad. Las colas son más seguras que variables globales.' },

  // ---------- Motores (b4) ----------
  { id: 'fc-043', track: 'robotica', module: 'b4', front: '¿Cómo se controla la velocidad y el sentido de un motor DC?', back: 'La velocidad es aproximadamente proporcional al voltaje aplicado y el par a la corriente. Invertir la polaridad invierte el giro; con PWM se regula el voltaje medio.' },
  { id: 'fc-044', track: 'robotica', module: 'b4', front: '¿Qué es el par de arranque (stall torque)?', back: 'Es el par máximo, que aparece con el motor parado. Allí la corriente es máxima (I = V/R) y el devanado se calienta rápido: un motor bloqueado puede quemarse.', hint: 'Velocidad cero, corriente máxima' },
  { id: 'fc-045', track: 'robotica', module: 'b4', front: '¿Qué es el back-EMF de un motor?', back: 'Es el voltaje que genera el motor al girar y que se opone a la alimentación. Crece con la velocidad y limita la corriente a altas revoluciones.' },
  { id: 'fc-046', track: 'robotica', module: 'b4', front: '¿Qué es un puente H?', back: 'Cuatro interruptores dispuestos en forma de H que permiten aplicar voltaje en ambos sentidos al motor y frenarlo. Es la etapa de potencia estándar para motores DC.', hint: 'Cuatro FET, dos ramas' },
  { id: 'fc-047', track: 'robotica', module: 'b4', front: '¿Qué es el shoot-through en un puente H?', back: 'Es activar a la vez los dos transistores de una misma rama, lo que cortocircuita la fuente a masa. Se evita con dead-time: una pequeña pausa entre conmutaciones complementarias.' },
  { id: 'fc-048', track: 'robotica', module: 'b4', front: '¿Qué es el frenado regenerativo?', back: 'El motor actúa como generador y devuelve energía al bus de alimentación. Solo funciona si la fuente puede absorberla; si no, el voltaje del bus sube y hace falta una resistencia de descarga.' },
  { id: 'fc-049', track: 'robotica', module: 'b4', front: '¿Qué es un motor paso a paso?', back: 'Gira en increments discretos activando bobinas en secuencia. Sin realimentación, la posición se estima contando pasos, siempre que no se pierdan.', hint: 'Stepper = posición por conteo' },
  { id: 'fc-050', track: 'robotica', module: 'b4', front: '¿Qué diferencia un stepper bipolar de uno unipolar?', back: 'El bipolar tiene dos bobinas y cuatro cables, y necesita un puente H por bobina; da más par. El unipolar tiene seis cables con punto medio y conmuta más fácil, pero aprovecha menos el devanado.' },
  { id: 'fc-051', track: 'robotica', module: 'b4', front: '¿Qué es el microstepping?', back: 'Dividir cada paso completo en fracciones controlando corrientes parciales en las dos bobinas. Gana suavidad y resolución, pero pierde par por micropaso y la precisión absoluta no mejora.', hint: 'Corriente sinusoidal en las bobinas' },
  { id: 'fc-052', track: 'robotica', module: 'b4', front: '¿Cómo se manda un servo RC?', back: 'Con PWM de 50 Hz (periodo 20 ms) donde el ancho del pulso indica posición: 1 ms a un extremo, 1.5 ms al centro y 2 ms al otro. Internamente lleva potenciómetro y lazo de control.' },
  { id: 'fc-053', track: 'robotica', module: 'b4', front: '¿Por qué un servo RC no gira 360 grados?', back: 'Porque el potenciómetro mide posición y el controlador la mantiene dentro de un rango de unos 0-180 grados. En un servo de rotación continua se quita esa referencia y el pulso controla velocidad.' },
  { id: 'fc-054', track: 'robotica', module: 'b4', front: '¿Qué es un motor BLDC?', back: 'Un motor sin escobillas: los imanes están en el rotor y las bobinas en el estator. No hay desgaste de cepillos, pero hace falta conmutación electrónica para girarlo.' },
  { id: 'fc-055', track: 'robotica', module: 'b4', front: '¿Qué es FOC (Field-Oriented Control)?', back: 'Controla un BLDC transformando las corrientes trifásicas a un marco giratorio dq, donde par y flujo son independientes. Da par suave, alto rendimiento y buen control a baja velocidad.' },
  { id: 'fc-056', track: 'robotica', module: 'b4', front: '¿Qué hacen las transformadas de Clarke y Park en FOC?', back: 'Clarke pasa de las tres fases abc a dos ejes estacionarios alfa-beta; Park lleva esos ejes al marco rotante dq. En dq el control se parece al de un motor DC.', hint: '3 fases → 2 ejes → marco giratorio' },
  { id: 'fc-057', track: 'robotica', module: 'b4', front: '¿Qué es un encoder incremental?', back: 'Emite pulsos A y B (y a veces un índice Z) al girar. La posición se obtiene contando desde un origen, así que se pierde al apagar y requiere una rutina de home.' },
  { id: 'fc-058', track: 'robotica', module: 'b4', front: '¿Qué es un encoder absoluto?', back: 'Devuelve la posición real del eje incluso después de apagar, mediante código Gray o un protocolo como SPI/I2C. No necesita buscar el origen al arrancar.', hint: 'No cuenta desde cero: sabe dónde está' },
  { id: 'fc-059', track: 'robotica', module: 'b4', front: '¿Para qué sirven los canales A y B en cuadratura?', back: 'Están desfasados 90 grados, lo que permite saber el sentido de giro según cuál adelanta. Además se puede contar flanco ascendente y descendente de ambos para multiplicar la resolución por cuatro.' },
  { id: 'fc-060', track: 'robotica', module: 'b4', front: '¿Qué es un brownout?', back: 'Una caída transitoria del voltaje de alimentación, típica cuando arrancan motores o entran en transmisión. El microcontrolador puede reiniciarse, borrar variables o ejecutar instrucciones inválidas.' },
  { id: 'fc-061', track: 'robotica', module: 'b4', front: '¿Cómo se mitiga un brownout?', back: 'Separando la alimentación lógica de la de potencia, añadiendo condensadores grandes cerca del driver, usando cableado grueso y activando el reset por bajo voltaje del MCU.', hint: 'El ruido de los motores no debe llegar al chip' },
  { id: 'fc-062', track: 'robotica', module: 'b4', front: '¿Qué es el BOR (Brown-Out Reset)?', back: 'Un circuito interno del microcontrolador que lo reinicia cuando Vcc cae por debajo de un umbral configurado. Así se evita que el código siga corriendo con niveles de lógica inválidos.' },

  // ---------- Sensores y estimación (b5) ----------
  { id: 'fc-063', track: 'robotica', module: 'b5', front: '¿Qué mide un acelerómetro?', back: 'Aceleración específica, que incluye la gravedad. En reposo sobre una mesa mide 1 g hacia arriba, no cero.', hint: 'La gravedad cuenta como aceleración' },
  { id: 'fc-064', track: 'robotica', module: 'b5', front: '¿Qué mide un giroscopio?', back: 'Velocidad angular en los tres ejes, normalmente en rad/s o grados/s. Al integrarla se obtiene un ángulo, pero cualquier sesgo acumula deriva con el tiempo.' },
  { id: 'fc-065', track: 'robotica', module: 'b5', front: '¿Qué aporta un magnetómetro a una IMU?', back: 'Mide el campo magnético terrestre para estimar la orientación respecto al norte (yaw). Es muy sensible a metales, imanes y corrientes cercanas, así que hay que calibrarlo.' },
  { id: 'fc-066', track: 'robotica', module: 'b5', front: '¿Por qué deriva el ángulo de un giroscopio?', back: 'Porque el sensor tiene un pequeño sesgo que, al integrarse, crece linealmente sin límite. Por eso se fusiona con el acelerómetro y el magnetómetro, que no derivan pero sí son ruidosos.' },
  { id: 'fc-067', track: 'robotica', module: 'b5', front: '¿Qué hace un filtro complementario?', back: 'Combina el giroscopio a corto plazo (poco ruido) con el acelerómetro a largo plazo (sin deriva): integra el giro y mezcla con la inclinación estimada por gravedad mediante un peso pequeño.' },
  { id: 'fc-068', track: 'robotica', module: 'b5', front: '¿Qué controla la constante de tiempo en un filtro complementario?', back: 'Cuánto se confía en cada sensor. Un tau grande sigue más al giroscopio (suave pero puede tardar en corregir); un tau pequeño reacciona rápido al acelerómetro pero mete más ruido.', hint: 'alpha = dt/(tau + dt)' },
  { id: 'fc-069', track: 'robotica', module: 'b5', front: '¿Qué hace un filtro de Kalman?', back: 'Estima el estado de un sistema combinando una predicción de modelo con una medición ruidosa, ponderadas por sus covarianzas. Da una estimación óptima en el sentido de mínima varianza bajo supuestos gaussianos.' },
  { id: 'fc-070', track: 'robotica', module: 'b5', front: '¿Cuáles son los dos pasos de un filtro de Kalman?', back: 'Predicción: propaga el estado y su covarianza con el modelo. Actualización: compara con la medición y corrige usando la ganancia de Kalman.', hint: 'Predecir, luego corregir' },
  { id: 'fc-071', track: 'robotica', module: 'b5', front: '¿Qué significa la ganancia de Kalman K?', back: 'Es el peso relativo entre predicción y medición. Si la medición es muy fiable K tiende a 1; si el modelo es muy fiable, K tiende a 0.' },
  { id: 'fc-072', track: 'robotica', module: 'b5', front: '¿Qué es un sensor ToF?', back: 'Mide distancia cronometrando el viaje de la luz hasta el objeto y de vuelta. Puede ser iToF (mide desplazamiento de fase) o dToF (cuenta el tiempo de vuelo directo).' },
  { id: 'fc-073', track: 'robotica', module: 'b5', front: '¿Qué diferencia un sensor ToF de un ultrasonido?', back: 'El ToF usa luz: es rápido, con haz estrecho, pero lo afecta la luz solar y las superficies negras. El ultrasonido es barato y de haz ancho, pero lento y con resolución pobre.' },
  { id: 'fc-074', track: 'robotica', module: 'b5', front: '¿Qué entrega un LiDAR 2D?', back: 'Un escaneo de distancias en un plano: una lista de ángulos y rangos (scan). Es la base de la navegación y SLAM 2D en robots móviles.', hint: 'Un láser que gira' },
  { id: 'fc-075', track: 'robotica', module: 'b5', front: '¿Qué es un LiDAR 3D?', back: 'Un sensor que mide distancias en múltiples planos y produce una nube de puntos con coordenadas x,y,z e intensidad. Permite mapas 3D y detección de obstáculos en altura.' },
  { id: 'fc-076', track: 'robotica', module: 'b5', front: '¿Qué es la odometría?', back: 'La estimación de la posición y orientación integrando las lecturas de los encoders (y a veces la IMU) desde un punto inicial conocido. Es local y acumula error.' },
  { id: 'fc-077', track: 'robotica', module: 'b5', front: '¿Cómo se calcula la odometría de un robot diferencial?', back: 'Con v = (v_izq + v_der)/2 y omega = (v_der - v_izq)/L, donde L es la distancia entre ruedas. Se integran en el tiempo para obtener x, y y theta.', hint: 'Dos ruedas, sin dirección' },
  { id: 'fc-078', track: 'robotica', module: 'b5', front: '¿Por qué la odometría acumula error?', back: 'Pequeños errores en el radio de rueda, la separación entre ruedas y el resbalamiento se integran en cada paso y crecen sin límite. Nunca es una referencia absoluta.', hint: 'Deriva (drift)' },
  { id: 'fc-079', track: 'robotica', module: 'b5', front: '¿Qué es el resbalamiento de las ruedas y cómo se detecta?', back: 'La rueda gira pero el robot no avanza lo esperado, por suelo resbaladizo o giros bruscos. Se detecta comparando la odometría con IMU, visión o LiDAR.' },
  { id: 'fc-080', track: 'robotica', module: 'b5', front: '¿Cómo se corrige la odometría?', back: 'Fusionándola con sensores absolutos o con SLAM mediante un filtro de Kalman, de partículas o graph SLAM. La odometría aporta suavidad entre correcciones; no define la posición global.' },

  // ---------- ROS 2 (b7) ----------
  { id: 'fc-081', track: 'robotica', module: 'b7', front: '¿Qué es un nodo en ROS 2?', back: 'Un proceso que realiza cómputo y se comunica con otros nodos mediante topics, services o actions. Es la unidad básica del grafo y se escribe con rclpy o rclcpp.' },
  { id: 'fc-082', track: 'robotica', module: 'b7', front: '¿Qué es un topic en ROS 2?', back: 'Un canal de comunicación publish/subscribe, asíncrono y many-to-many. Los nodos publican mensajes de un tipo concreto y otros se suscriben sin conocer quién los emite.' },
  { id: 'fc-083', track: 'robotica', module: 'b7', front: '¿Qué es un mensaje .msg en ROS 2?', back: 'Una estructura de datos tipada con campos primitivos o compuestos, definida en un archivo .msg. A partir de ella se genera el código C++/Python para publicar y suscribirse.' },
  { id: 'fc-084', track: 'robotica', module: 'b7', front: '¿Qué son los perfiles QoS en ROS 2?', back: 'Políticas de comunicación: reliability, durability, history, deadline y lifespan. Best effort prioriza velocidad y reliable garantiza entrega; ambos extremos deben ser compatibles.', hint: 'Por eso a veces un nodo no ve a otro' },
  { id: 'fc-085', track: 'robotica', module: 'b7', front: '¿Qué es un service en ROS 2?', back: 'Una comunicación de petición-respuesta, síncrona y normalmente uno-a-uno. Conviene para consultas o comandos cortos que requieren confirmación.' },
  { id: 'fc-086', track: 'robotica', module: 'b7', front: '¿Qué es una action en ROS 2?', back: 'Una comunicación con objetivo, feedback periódico y resultado final, además de cancelación y preempting. Está pensada para tareas largas como navegar hasta un punto.' },
  { id: 'fc-087', track: 'robotica', module: 'b7', front: '¿Qué diferencia un service de una action?', back: 'El service bloquea hasta la respuesta y no informa de progreso; la action es asíncrona, publica feedback y se puede cancelar. Un service para "leer temperatura", una action para "ir a la cocina".' },
  { id: 'fc-088', track: 'robotica', module: 'b7', front: '¿Qué son los parámetros en ROS 2?', back: 'Valores configurables de cada nodo (declare_parameter, set_parameter) que se pueden cambiar en tiempo de ejecución. A diferencia de ROS 1, no hay un servidor global de parámetros.' },
  { id: 'fc-089', track: 'robotica', module: 'b7', front: '¿Qué hace tf2?', back: 'Mantiene el árbol de transformaciones entre sistemas de coordenadas y permite convertir poses y vectores de un frame a otro en cualquier instante.', hint: 'Responde: ¿dónde está este punto respecto a base_link?' },
  { id: 'fc-090', track: 'robotica', module: 'b7', front: '¿Qué regla debe cumplir el árbol de tf2?', back: 'Cada frame tiene un único padre y no puede haber ciclos. Solo así hay una cadena de transformaciones inequívoca entre cualquier par de frames.' },
  { id: 'fc-091', track: 'robotica', module: 'b7', front: '¿Por qué importa el tiempo en tf2?', back: 'Las transformaciones cambian con el tiempo porque el robot se mueve. Hay que pedir la transformación en el instante de la medición y manejar extrapoliciones o timeouts con cuidado.' },
  { id: 'fc-092', track: 'robotica', module: 'b7', front: '¿Qué es un static_transform_publisher?', back: 'Publica una vez una transformación fija, por ejemplo entre base_link y el LiDAR, con durabilidad transient_local. Evita llenar el bus con la misma transformación en cada ciclo.' },
  { id: 'fc-093', track: 'robotica', module: 'b7', front: '¿Qué describe un archivo URDF?', back: 'La estructura del robot en XML: links (cuerpos) unidos por joints, con geometría, inercia, ejes, límites y colisiones. Se usa en RViz, Gazebo y ros2_control.' },
  { id: 'fc-094', track: 'robotica', module: 'b7', front: '¿Qué diferencia los joints fixed, revolute y continuous en URDF?', back: 'Fixed no tiene movimiento; revolute gira dentro de límites inferiores y superiores; continuous gira sin límite. Prismatic desliza en línea recta.', hint: 'Piensa en una bisagra, una rueda y un tornillo' },
  { id: 'fc-095', track: 'robotica', module: 'b7', front: '¿Qué es ros2_control?', back: 'El framework de ROS 2 para abstraer el hardware y gestionar controladores. La descripción del hardware va en el URDF y los controladores se cargan en tiempo de ejecución.' },
  { id: 'fc-096', track: 'robotica', module: 'b7', front: '¿Qué hacen hardware_interface y controller_manager?', back: 'La hardware_interface es el puente entre el código de control y los motores reales o de simulación; el controller_manager carga y arranca controladores como joint_state_broadcaster o diff_drive_controller.' },
  { id: 'fc-097', track: 'robotica', module: 'b7', front: '¿Qué es Gazebo en el ecosistema ROS 2?', back: 'Un simulador físico 3D que modela gravedad, colisiones, fricción y sensores con ruido. Permite probar robots antes de tener hardware; hoy conviven las líneas Ignition y Classic.' },
  { id: 'fc-098', track: 'robotica', module: 'b7', front: '¿Qué piezas incluye Nav2?', back: 'Localización (AMCL), mapas de coste, planificador global, controlador local, behaviors de recuperación y waypoint following. Es la pila de navegación estándar de ROS 2.', hint: 'Responde: ¿dónde estoy, por dónde voy, cómo llego?' },
  { id: 'fc-099', track: 'robotica', module: 'b7', front: '¿Qué es un costmap en Nav2?', back: 'Un mapa de ocupación que infla los obstáculos según el radio del robot. Existe una capa global para planificar y otra local para reaccionar en tiempo real.' },
  { id: 'fc-100', track: 'robotica', module: 'b7', front: '¿Qué significa SLAM en robótica?', back: 'Localización y mapeo simultáneos: el robot construye un mapa mientras calcula su posición dentro de él. En ROS 2 se usan slam_toolbox para 2D y LIO-SAM o similares para 3D.', hint: 'Chicken-and-egg: necesito el mapa para ubicarme' },
  { id: 'fc-101', track: 'robotica', module: 'b7', front: '¿Qué es AMCL?', back: 'Adaptive Monte Carlo Localization: un filtro de partículas que estima la pose del robot sobre un mapa conocido, corrigiendo la odometría con las lecturas del LiDAR.' },
  { id: 'fc-102', track: 'robotica', module: 'b7', front: '¿Qué es MoveIt 2?', back: 'El framework de ROS 2 para brazos robóticos: cinemática inversa, planificación de movimiento, detección de colisiones y ejecución de trayectorias en el controlador.' },
  { id: 'fc-103', track: 'robotica', module: 'b7', front: '¿Qué hace un planificador de movimiento en MoveIt?', back: 'Busca una trayectoria libre de colisiones en el espacio de configuraciones del brazo. OMPL aporta algoritmos como RRT, PRM, CHOMP y STOMP.', hint: 'No planea en el espacio cartesiano directamente' },
  { id: 'fc-104', track: 'robotica', module: 'b7', front: '¿Para qué se usa RViz?', back: 'Para visualizar en 3D los topics del robot: imágenes, nubes de puntos, mapas, el árbol tf, marcadores y trayectorias. Es la herramienta de depuración visual de ROS 2.' },
  { id: 'fc-105', track: 'robotica', module: 'b7', front: '¿Qué es un rosbag en ROS 2?', back: 'Un archivo que graba y reproduce mensajes de topics con su marca de tiempo. Permite depurar, repetir experimentos y compartir datos reales sin el robot.' },
  { id: 'fc-106', track: 'robotica', module: 'b7', front: '¿Qué es DDS en ROS 2?', back: 'El middleware de comunicación subyacente (Data Distribution Service). Aporta descubrimiento dinámico y políticas QoS, algo de lo que carecía el ROS 1 centralizado.' },

  // ---------- Control y cinemática (b8) ----------
  { id: 'fc-107', track: 'robotica', module: 'b8', front: '¿Qué hace el término proporcional de un PID?', back: 'Corrige en proporción al error actual. Reduce el error rápidamente, pero deja un error permanente si se usa solo y puede oscilar si Kp es demasiado alto.' },
  { id: 'fc-108', track: 'robotica', module: 'b8', front: '¿Qué hace el término integral de un PID?', back: 'Acumula los errores pasados para eliminar el error permanente. Si el actuador se satura, el acumulador puede crecer demasiado: es el windup.', hint: 'Suma la historia del error' },
  { id: 'fc-109', track: 'robotica', module: 'b8', front: '¿Qué hace el término derivativo de un PID?', back: 'Reacciona a la velocidad de cambio del error, amortiguando el sistema y reduciendo el sobreimpulso. Amplifica el ruido de la medición, por eso a menudo se filtra.' },
  { id: 'fc-110', track: 'robotica', module: 'b8', front: '¿Qué es el anti-windup?', back: 'Limitar o congelar el integrador cuando la salida está saturada, evitando que al salir de la saturación el controlador siga acumulando un gran error. Es esencial en motores con límite de PWM.' },
  { id: 'fc-111', track: 'robotica', module: 'b8', front: '¿Qué es un modelo en espacio de estados?', back: 'Describe el sistema con un vector de estado: x(k+1) = A x(k) + B u(k), y(k) = C x(k) + D u(k). Permite manejar múltiples entradas y salidas y diseñar controladores modernos.' },
  { id: 'fc-112', track: 'robotica', module: 'b8', front: '¿Qué significan controlabilidad y observabilidad?', back: 'Controlabilidad: se puede llevar el estado a cualquier valor con una entrada adecuada. Observabilidad: se puede reconstruir el estado a partir de las salidas. Los diseños LQR y observadores las requieren.' },
  { id: 'fc-113', track: 'robotica', module: 'b8', front: '¿Qué optimiza un controlador LQR?', back: 'Minimiza una función de coste suma de xᵀQx + uᵀRu a lo largo del tiempo. La matriz de realimentación K se obtiene resolviendo la ecuación de Riccati.' },
  { id: 'fc-114', track: 'robotica', module: 'b8', front: '¿Qué efecto tienen las matrices Q y R en un LQR?', back: 'Q penaliza alejarse del estado deseado: mayor Q, control más agresivo. R penaliza el esfuerzo de control: mayor R, control más suave y conservador.' },
  { id: 'fc-115', track: 'robotica', module: 'b8', front: '¿Qué es MPC (control predictivo por modelo)?', back: 'En cada paso optimiza una secuencia futura de controles con un modelo del sistema, aplica solo el primero y vuelve a optimizar (horizonte deslizante). Su gran ventaja es manejar restricciones explícitamente.', hint: 'Receding horizon' },
  { id: 'fc-116', track: 'robotica', module: 'b8', front: '¿Qué es la cinemática directa?', back: 'Dados los ángulos o desplazamientos articulares, calcula la pose del efector final. Se compone transformaciones homoténeas entre eslabones, por Denavit-Hartenberg o productos de exponenciales.' },
  { id: 'fc-117', track: 'robotica', module: 'b8', front: '¿Qué es la cinemática inversa?', back: 'Dada la pose deseada del efector, obtiene los valores articulares que la producen. Puede tener varias soluciones, una sola o ninguna si el objetivo está fuera del espacio de trabajo.' },
  { id: 'fc-118', track: 'robotica', module: 'b8', front: '¿Qué es el Jacobiano de un robot?', back: 'La matriz que relaciona velocidades articulares con la velocidad lineal y angular del efector: ẋ = J(q)·q̇. Por dualidad también transforma fuerzas del efector en pares articulares: τ = JᵀF.' },
  { id: 'fc-119', track: 'robotica', module: 'b8', front: '¿Qué es una configuración singular?', back: 'Una postura donde el Jacobiano pierde rango: el brazo no puede moverse en alguna dirección y los pares necesarios pueden hacerse infinitos. Conviene evitarla en la planificación.', hint: 'Brazo totalmente estirado' },
  { id: 'fc-120', track: 'robotica', module: 'b8', front: '¿Qué mide el índice de manipulabilidad?', back: 'El menor valor singular del Jacobiano (o su recíproco, el número de condición). Cuanto mayor, más lejos está el robot de una singularidad y mejor será la precisión en esa dirección.' },
  { id: 'fc-121', track: 'robotica', module: 'b8', front: '¿Qué es un perfil de velocidad trapezoidal?', back: 'Aceleración constante, fase de velocidad constante y desaceleración constante. Es fácil de implementar, pero el cambio brusco de aceleración genera un jerk infinito en las esquinas.' },
  { id: 'fc-122', track: 'robotica', module: 'b8', front: '¿Qué es un perfil S-curve?', back: 'Un perfil que limita el jerk (la derivada de la aceleración), suavizando las transiciones. Reduce vibraciones y esfuerzos mecánicos en brazos y ejes de alta velocidad.', hint: 'La curva de velocidad tiene forma de S' },
  { id: 'fc-123', track: 'robotica', module: 'b8', front: '¿Qué diferencia interpolación articular de interpolación cartesiana?', back: 'En articular se interpolan los ángulos: simple y siempre alcanzable, pero el efector sigue una curva. En cartesiana se interpola la pose del efector y se resuelve la IK en cada paso: trayectoria recta, más costosa.' },
  { id: 'fc-124', track: 'robotica', module: 'b8', front: '¿Cómo se elige el periodo de muestreo de un lazo de control?', back: 'Debe ser mucho menor que la constante de tiempo del sistema, típicamente unas 10-20 veces más rápido. Muestrear demasiado lento añade retraso de fase y puede desestabilizar el lazo.' },
  { id: 'fc-125', track: 'robotica', module: 'b8', front: '¿Qué hace un filtro pasa-bajo en un lazo de control?', back: 'Atenúa el ruido de alta frecuencia de los sensores, pero introduce retraso de fase que reduce el margen de estabilidad. Hay que equilibrar ruido y fase.', hint: 'Todo filtro cuesta fase' },
  { id: 'fc-126', track: 'robotica', module: 'b8', front: '¿Qué son el margen de fase y el margen de ganancia?', back: 'Midan cuánto puede aumentar el retraso de fase o la ganancia antes de que el lazo se vuelva inestable. Como referencia se buscan 45-60 grados de margen de fase y 6-10 dB de ganancia.' },
  { id: 'fc-127', track: 'robotica', module: 'b8', front: '¿Qué es el control feedforward?', back: 'Añadir una acción anticipada calculada del modelo (gravedad, fricción, aceleración deseada) además del feedback. Mejora el seguimiento sin tener que subir Kp y generar ruido u oscilaciones.' },
  { id: 'fc-128', track: 'robotica', module: 'b8', front: '¿Qué es un lazo de control en cascada?', back: 'Varios lazos anidados: el interno controla corriente o velocidad y el externo posición. El lazo interno debe ser varias veces más rápido que el externo para que este pueda tratarlo como ideal.' },

  // ---------- Visión (b9) ----------
  { id: 'fc-129', track: 'robotica', module: 'b9', front: '¿Qué hace una convolución sobre una imagen?', back: 'Desliza un pequeño kernel sobre la imagen y combina píxeles vecinos con pesos compartidos. Según el kernel extrae bordes, texturas o patrones de nivel superior.' },
  { id: 'fc-130', track: 'robotica', module: 'b9', front: '¿Qué son padding y stride en una convolución?', back: 'Padding añade píxeles en los bordes para conservar el tamaño de la salida; stride es el paso con que se desplaza el kernel. Un stride mayor reduce resolución y coste.' },
  { id: 'fc-131', track: 'robotica', module: 'b9', front: '¿Para qué sirve una capa de pooling?', back: 'Reduce el tamaño espacial con max o average pooling. Disminuye parámetros y cálculo, y aporta cierta invariancia a pequeños desplazamientos.', hint: 'Max pooling conserva las activaciones fuertes' },
  { id: 'fc-132', track: 'robotica', module: 'b9', front: '¿Qué estima la calibración intrínseca de una cámara?', back: 'Distancia focal (fx, fy), centro óptico (cx, cy) y coeficientes de distorsión. Se calcula observando un tablero de ajedrez desde varios ángulos.' },
  { id: 'fc-133', track: 'robotica', module: 'b9', front: '¿Qué son los parámetros extrínsecos de una cámara?', back: 'La rotación R y traslación t que llevan puntos del marco de la cámara al marco del robot o del mundo. Responden a dónde está y cómo está orientada la cámara.' },
  { id: 'fc-134', track: 'robotica', module: 'b9', front: '¿Qué es la distorsión de barril?', back: 'Las líneas rectas del mundo se ven curvadas hacia fuera por el objetivo gran angular. Se corrige con los coeficientes radiales y tangenciales del modelo de Brown-Conrady.' },
  { id: 'fc-135', track: 'robotica', module: 'b9', front: '¿Cómo se obtiene profundidad con visión estéreo?', back: 'Con dos cámaras separadas una base B, la disparidad d = x_izq - x_der da Z = f·B/d. A mayor disparidad, el punto está más cerca.', hint: 'Triángulo semejante: la fórmula clave de estéreo' },
  { id: 'fc-136', track: 'robotica', module: 'b9', front: '¿Cómo afecta la base entre cámaras a la visión estéreo?', back: 'Una base mayor mejora la precisión en distancias lejanas, pero reduce el rango de disparidades que se pueden medir y aumenta las zonas de oclusión.' },
  { id: 'fc-137', track: 'robotica', module: 'b9', front: '¿Qué es la rectificación epipolar?', back: 'Tras calibrar, se deforman las imágenes para que las líneas epipolares sean horizontales. Así el punto correspondiente está en la misma fila y la búsqueda pasa de 2D a 1D.' },
  { id: 'fc-138', track: 'robotica', module: 'b9', front: '¿Qué es una nube de puntos?', back: 'Un conjunto de puntos 3D con coordenadas x, y, z, a veces con intensidad o color. Suele venir de un LiDAR o de una cámara de profundidad.' },
  { id: 'fc-139', track: 'robotica', module: 'b9', front: '¿Qué hace un filtro de voxel grid sobre una nube de puntos?', back: 'Divide el espacio en celdas cúbicas y las sustituye por un único punto representativo. Reduce densidad y acelera algoritmos como SLAM o detección, con pérdidaControlada de detalle.', hint: 'Downsampling 3D' },
  { id: 'fc-140', track: 'robotica', module: 'b9', front: '¿Cómo se ajusta un plano con RANSAC?', back: 'Se muestrean hipótesis mínimas de tres puntos, se cuenta cuántos puntos caen dentro de un umbral (inliers) y se conserva el mejor modelo. Es robusto frente a outliers como obstáculos sobre el suelo.' },
  { id: 'fc-141', track: 'robotica', module: 'b9', front: '¿Qué es YOLO?', back: 'Un detector de objetos de una sola etapa: divide la imagen en una rejilla y predice cajas y clases en un único paso. Prioriza velocidad para tiempo real.', hint: 'You Only Look Once' },
  { id: 'fc-142', track: 'robotica', module: 'b9', front: '¿Qué es IoU y dónde se usa?', back: 'Intersection over Union: área de solapamiento entre la caja predicha y la real dividida por su unión. Mide qué tan buena es la detección y se usa en NMS y mAP.' },
  { id: 'fc-143', track: 'robotica', module: 'b9', front: '¿Qué hace NMS en detección de objetos?', back: 'Suprime cajas duplicadas de la misma clase: ordena por confianza y descarta las que solapan mucho (IoU alto) con una mejor. Así queda una detección por objeto.' },
  { id: 'fc-144', track: 'robotica', module: 'b9', front: '¿Qué es SLAM visual?', back: 'Estimar la trayectoria de la cámara y reconstruir un mapa 3D del entorno simultáneamente a partir de imágenes, sin GPS ni marcas artificiales.' },
  { id: 'fc-145', track: 'robotica', module: 'b9', front: '¿Cómo funciona un vSLAM basado en características?', back: 'Detecta puntos distintivos (ORB, SIFT), los empareja entre fotogramas, estima el movimiento de la cámara y optimiza todo con bundle adjustment.', hint: 'Features → matches → optimización' },
  { id: 'fc-146', track: 'robotica', module: 'b9', front: '¿Qué es el bundle adjustment?', back: 'Optimización conjunta de las poses de cámara y las posiciones 3D de los puntos para minimizar el error de reproyección de todos los puntos observados. Es el paso final típico de SLAM y calibración.' },

  // ---------- Robot learning (b10) ----------
  { id: 'fc-147', track: 'robotica', module: 'b10', front: '¿Qué es el behavior cloning?', back: 'Aprendizaje por imitación que entrena una política para mapear observaciones a acciones usando demostraciones de un experto. Es simple, pero sufre al salir de la distribución de datos.', hint: 'Supervised learning sobre demostraciones' },
  { id: 'fc-148', track: 'robotica', module: 'b10', front: '¿Qué es el error de compounding en behavior cloning?', back: 'Un pequeño error de la política lleva al robot a estados nunca vistos en el entrenamiento, donde comete errores mayores. Se mitiga con más datos, DAgger o modelos que predicen secuencias de acciones.' },
  { id: 'fc-149', track: 'robotica', module: 'b10', front: '¿Qué es ACT (Action Chunking with Transformers)?', back: 'Una política que usa un Transformer para predecir un bloque de acciones futuras a la vez, en lugar de una sola. Reduce el error de compounding y produce movimientos más coherentes.', hint: 'Chunk = trozo de trayectoria' },
  { id: 'fc-150', track: 'robotica', module: 'b10', front: '¿Qué es el temporal ensemble en ACT?', back: 'Promediar las predicciones de varios chunks que se solapan en el tiempo. Suaviza la acción ejecutada y evita saltos entre predicciones consecutivas.' },
  { id: 'fc-151', track: 'robotica', module: 'b10', front: '¿Qué es una política de difusión en robótica?', back: 'Un modelo que aprende a eliminar ruido de una secuencia de acciones partiendo de ruido aleatorio, condicionado a las observaciones. Diffusion Policy maneja bien acciones multimodales.' },
  { id: 'fc-152', track: 'robotica', module: 'b10', front: '¿Qué ventaja tiene difusión sobre BC con acciones multimodales?', back: 'En vez de promediar varias formas válidas de hacer la tarea (que puede dar una acción inválida), la difusión puede generar cualquiera de los modos. Es clave en tareas con múltiples soluciones.', hint: 'Promediar dos caminos puede dar un punto medio malo' },
  { id: 'fc-153', track: 'robotica', module: 'b10', front: '¿Qué es reinforcement learning?', back: 'Un agente aprende una política interactuando con el entorno y maximizando la recompensa acumulada. No necesita demostraciones, pero sí una señal de recompensa y mucha interacción.' },
  { id: 'fc-154', track: 'robotica', module: 'b10', front: '¿Qué diferencia una recompensa densa de una escasa?', back: 'La densa da señal en cada paso, facilita el aprendizaje pero puede introducir sesgos; la escasa solo premia al completar la tarea, es más realista pero muy difícil de explorar.' },
  { id: 'fc-155', track: 'robotica', module: 'b10', front: '¿Qué es el dilemma exploración-explotación en RL?', back: 'Explorar sirve para descubrir recompensas mejores; explotar sirve para ganar más con lo ya aprendido. Políticas como epsilon-greedy o la entropía controlan este equilibrio.' },
  { id: 'fc-156', track: 'robotica', module: 'b10', front: '¿Qué es el sim-to-real gap?', back: 'La diferencia entre la dinámica y los sensores del simulador y los del robot real. Una política entrenada en simulación puede caer bastante al desplegarse por ese desajuste.' },
  { id: 'fc-157', track: 'robotica', module: 'b10', front: '¿Qué es el domain randomization?', back: 'Variar al entrenar parámetros del simulador como masa, fricción, iluminación, texturas o retardos. El objetivo es que la política aprenda a ser robusta a cualquier combinación del mundo real.', hint: 'Haz el simulador impredecible a propósito' },
  { id: 'fc-158', track: 'robotica', module: 'b10', front: '¿Qué es el domain adaptation?', back: 'Ajustar el modelo o su representación para reducir la diferencia entre el dominio simulado y el real, por ejemplo adaptando imágenes o normalizando observaciones.' },
  { id: 'fc-159', track: 'robotica', module: 'b10', front: '¿Qué es LeRobot?', back: 'La librería de Hugging Face para robot learning: datasets de demostraciones, modelos como ACT o Diffusion Policy y herramientas de entrenamiento y despliegue en PyTorch.' },
  { id: 'fc-160', track: 'robotica', module: 'b10', front: '¿Qué contiene un dataset de demostraciones?', back: 'Secuencias de pares observación-acción: imágenes de cámaras, estado articular, comandos aplicados y metadatos de la tarea. El formato LeRobot facilita compartir y entrenar con ellas.' },
  { id: 'fc-161', track: 'robotica', module: 'b10', front: '¿Qué es la teleoperación en robot learning?', back: 'Controlar el robot con un dispositivo externo, como un brazo maestro, un joystick o gafas de realidad virtual, para generar demostraciones de alta calidad.' },
  { id: 'fc-162', track: 'robotica', module: 'b10', front: '¿Qué es un modelo VLA?', back: 'Vision-Language-Action: un modelo que toma imágenes e instrucciones en lenguaje natural y produce directamente acciones del robot. Ejemplos: RT-2 y OpenVLA.', hint: 'Visión + lenguaje → acción' },
  { id: 'fc-163', track: 'robotica', module: 'b10', front: '¿Qué es OpenVLA?', back: 'Un VLA de código abierto que combina un modelo de visión con un LLM tipo Llama 2 y se entrena con grandes datasets de manipulación. Busca generalizar a tareas y objetos nuevos.' },
  { id: 'fc-164', track: 'robotica', module: 'b10', front: '¿Cómo se tokenizan las acciones en un VLA?', back: 'Se discretiza cada dimensión de la acción en bins y esos bins se tratan como tokens del vocabulario. Así se puede reutilizar la arquitectura y el entrenamiento de modelos de lenguaje.' },

  // ---------- Matemáticas y ML (a1/a2) ----------
  { id: 'fc-165', track: 'ai', module: 'a1', front: '¿Qué es un vector?', back: 'Una lista ordenada de números que representa un punto en un espacio o una magnitud con dirección. En ML, una fila de datos o un embedding son vectores.' },
  { id: 'fc-166', track: 'ai', module: 'a1', front: '¿Qué es el producto punto?', back: 'Es suma de los productos componente a componente, y también |a|·|b|·cos(θ). Mide proyección y, si los vectores están normalizados, da la similitud coseno.' },
  { id: 'fc-167', track: 'ai', module: 'a1', front: '¿Qué significa multiplicar dos matrices?', back: 'Cada elemento de la resultado es el producto punto de una fila de la primera por una columna de la segunda. Una matriz (m×n) por otra (n×p) da (m×p) y representa la composición de transformaciones lineales.' },
  { id: 'fc-168', track: 'ai', module: 'a1', front: '¿Qué son autovectores y autovalores?', back: 'Si A·v = λ·v, v es autovector y λ su autovalor: la transformación solo lo escala. Indican las direcciones principales de la matriz y son la base de PCA.' },
  { id: 'fc-169', track: 'ambos', module: 'ambos', front: '¿Qué es el gradiente de una función?', back: 'El vector de sus derivadas parciales. Apunta en la dirección de mayor crecimiento; en optimización se avanza en dirección opuesta para minimizar.', hint: 'Cuesta abajo es -gradiente' },
  { id: 'fc-170', track: 'ambos', module: 'ambos', front: '¿Qué dice la regla de la cadena?', back: `La derivada de una composición es d/dx f(g(x)) = f'(g(x))·g'(x). Es el mecanismo que permite diferenciar redes profundas capa por capa.`, hint: 'Backprop la aplica en cada capa' },
  { id: 'fc-171', track: 'ai', module: 'a1', front: '¿Qué es el descenso de gradiente?', back: 'Actualizar los parámetros en dirección opuesta al gradiente de la pérdida: θ ← θ - η·∇L(θ). Se repite hasta convergencia o hasta agotar las épocas.' },
  { id: 'fc-172', track: 'ai', module: 'a1', front: '¿Qué pasa si el learning rate es demasiado alto?', back: 'Los pasos sobrepasan el mínimo y el entrenamiento oscila o diverge. Si es demasiado bajo, la convergencia es lenta o se queda en un mínimo poco bueno.', hint: 'Es el tamaño del paso' },
  { id: 'fc-173', track: 'ai', module: 'a2', front: '¿Qué es overfitting?', back: 'El modelo memoriza ruido o peculiaridades del entrenamiento y generaliza mal. Se detecta porque la pérdida en train sigue bajando mientras la de validación sube.' },
  { id: 'fc-174', track: 'ai', module: 'a2', front: '¿Qué es underfitting?', back: 'El modelo es demasiado simple para capturar la estructura de los datos: falla tanto en entrenamiento como en validación. Se corrige con más capacidad, mejores features o menos regularización.' },
  { id: 'fc-175', track: 'ai', module: 'a2', front: '¿Qué relación hay entre sesgo y varianza?', back: 'Error esperado = sesgo² + varianza + ruido irreducible. Más complejidad reduce el sesgo pero aumenta la varianza; el objetivo es el punto de equilibrio.' },
  { id: 'fc-176', track: 'ai', module: 'a2', front: '¿Qué hace la regularización L2?', back: 'Añade λ·||w||² a la pérdida, penalizando pesos grandes. Controla la varianza y favorece modelos más simples y estables.' },
  { id: 'fc-177', track: 'ai', module: 'a2', front: '¿Qué son precisión y recall?', back: 'Precisión = TP/(TP+FP): de lo que predije como positivo, cuánto acerté. Recall = TP/(TP+FN): de los positivos reales, cuántos encontré.', hint: 'Precisión habla de las predicciones; recall, de la realidad' },
  { id: 'fc-178', track: 'ai', module: 'a2', front: '¿Qué es la F1-score?', back: 'La media armónica entre precisión y recall. Penaliza los desequilibrios extremos y es útil cuando las clases están desbalanceadas.' },
  { id: 'fc-179', track: 'ai', module: 'a2', front: '¿Qué son la curva ROC y el AUC?', back: 'La ROC grafica tasa de verdaderos positivos contra tasa de falsos positivos al variar el umbral. El AUC es el área bajo esa curva: probabilidad de que un positivo puntúe más alto que un negativo.' },
  { id: 'fc-180', track: 'ambos', module: 'ambos', front: '¿Qué muestra una matriz de confusión?', back: 'Una tabla con verdaderos positivos y negativos y falsos positivos y negativos. Permite ver qué clases se confunden entre sí, algo que una única métrica oculta.' },
  { id: 'fc-181', track: 'ai', module: 'a2', front: '¿Qué es un árbol de decisión?', back: 'Modelo que particiona el espacio de features con reglas de umbral sucesivas. Es muy interpretable, pero sin poda o profundidad máxima tiende a overfit.' },
  { id: 'fc-182', track: 'ai', module: 'a2', front: '¿Qué es Random Forest?', back: 'Muchos árboles entrenados con muestras bootstrap y subconjuntos aleatorios de features; se promedian sus predicciones. Reduce la varianza de un árbol único.', hint: 'Bagging + random features' },
  { id: 'fc-183', track: 'ai', module: 'a2', front: '¿Qué es XGBoost?', back: 'Un método de boosting que entrena árboles en secuencia, cada uno corrigiendo los residuos de los anteriores, con regularización y optimización por gradientes. Suele ganar en datos tabulares.' },
  { id: 'fc-184', track: 'ai', module: 'a2', front: '¿Qué hace k-means?', back: 'Asigna cada punto al centroide más cercano y recoloca los centroides con la media del cluster, de forma iterativa. Es sensible a la inicialización, a la escala y al valor de k.' },
  { id: 'fc-185', track: 'ambos', module: 'ambos', front: '¿Qué es PCA?', back: 'Análisis de componentes principales: proyecta los datos sobre los autovectores de mayor varianza de la matriz de covarianza. Reduce dimensionalidad conservando la mayor parte de la información.' },
  { id: 'fc-186', track: 'ai', module: 'a2', front: '¿Qué es la validación cruzada k-fold?', back: 'Dividir los datos en k partes, entrenar k veces dejando una parte como test y promediar el resultado. Da una estimación más estable que un único split, siempre que no haya data leakage.', hint: 'Normaliza y separa antes de dividir' },

  // ---------- Deep learning (a3) ----------
  { id: 'fc-187', track: 'ai', module: 'a3', front: '¿Qué es backpropagation?', back: 'Calcular los gradientes de la pérdida respecto a todos los pesos aplicando la regla de la cadena desde la salida hacia atrás. Reutiliza los gradientes ya calculados en capas posteriores.' },
  { id: 'fc-188', track: 'ai', module: 'a3', front: '¿Qué es un grafo computacional?', back: 'Representación de las operaciones como nodos y dependencias. Permite a los frameworks hacer diferenciación automática y reutilizar el forward en el backward.' },
  { id: 'fc-189', track: 'ai', module: 'a3', front: '¿Qué es el vanishing gradient?', back: 'Los gradientes se vuelven exponencialmente pequeños al propagarse por muchas capas, y las primeras casi no aprenden. Se mitigó con ReLU, conexiones residuales y normalización.' },
  { id: 'fc-190', track: 'ai', module: 'a3', front: '¿Qué es el exploding gradient?', back: 'Los gradientes crecen desmesuradamente y los pesos dan saltos enormes. Se controla con gradient clipping, mejor inicialización y normalización.' },
  { id: 'fc-191', track: 'ai', module: 'a3', front: '¿Qué es una CNN?', back: 'Una red con capas convolucionales que comparten pesos y son equivariantes a traslación. Ahorra parámetros frente a una MLP y es la base de la visión por computador.' },
  { id: 'fc-192', track: 'ai', module: 'a3', front: '¿Qué produce un filtro en una CNN?', back: 'Cada kernel detecta un patrón concreto y genera un mapa de activaciones o canal. En capas profundas esos patrones se combinan en formas y objetos más complejos.' },
  { id: 'fc-193', track: 'ai', module: 'a3', front: '¿Qué es el campo receptivo?', back: 'La región de la entrada que influye en la activación de una unidad. Crece con la profundidad, el stride y la dilatación de las convoluciones.' },
  { id: 'fc-194', track: 'ai', module: 'a3', front: '¿Qué es una convolución dilatada?', back: 'Inserta huecos entre los elementos del kernel para ampliar el campo receptivo sin reducir resolución ni aumentar parámetros. Muy usada en segmentación y modelos de audio.' },
  { id: 'fc-195', track: 'ai', module: 'a3', front: '¿Qué es una RNN?', back: 'Una red con un estado oculto que se actualiza en cada paso de una secuencia, compartiendo pesos en el tiempo. Permite procesar entradas de longitud variable.' },
  { id: 'fc-196', track: 'ai', module: 'a3', front: '¿Cuál es el problema de una RNN con secuencias largas?', back: 'Olvida información lejana por vanishing gradient. LSTM y GRU introducen compuertas para conservar memoria durante más pasos.' },
  { id: 'fc-197', track: 'ai', module: 'a3', front: '¿Qué es un LSTM?', back: 'Una RNN con memoria celular y compuertas de olvido, entrada y salida que deciden qué información guardar o descartar en cada paso. Mitiga el olvido de largas dependencias.' },
  { id: 'fc-198', track: 'ai', module: 'a3', front: '¿Qué es el mecanismo de atención?', back: 'Para cada elemento, calcula pesos sobre todos los demás a partir de similitudes entre query y key, y agrega los value ponderados. El contexto depende de la propia entrada.' },
  { id: 'fc-199', track: 'ai', module: 'a3', front: '¿Qué es self-attention?', back: 'Atención donde queries, keys y values proceden de la misma secuencia. Cada token puede mirar a cualquier otro token, sin importar la distancia.', hint: 'Todo el mundo se mira con todo el mundo' },
  { id: 'fc-200', track: 'ai', module: 'a3', front: '¿Qué es un Transformer?', back: 'Una arquitectura basada en atención, sin recurrencia, con multi-head attention, redes feed-forward, conexiones residuales y normalización. Es altamente paralelizable durante el entrenamiento.' },
  { id: 'fc-201', track: 'ai', module: 'a3', front: '¿Qué es multi-head attention?', back: 'Varias operaciones de atención en paralelo, cada una con proyecciones aprendidas distintas. Cada cabeza puede capturar un tipo de relación diferente entre tokens.' },
  { id: 'fc-202', track: 'ai', module: 'a3', front: '¿Qué es BatchNorm?', back: 'Normaliza las activaciones usando estadísticas del minibatch, con media y varianza móviles para inferencia. Acelera entrenamiento, pero depende del tamaño de batch y de que train y test tengan distribuciones parecidas.' },
  { id: 'fc-203', track: 'ai', module: 'a3', front: '¿Qué es LayerNorm?', back: 'Normaliza las características de cada muestra individualmente, sin depender del batch. Es la normalización estándar en Transformers.' },
  { id: 'fc-204', track: 'ai', module: 'a3', front: '¿Qué hace el dropout?', back: 'Desactiva aleatoriamente neuronas durante el entrenamiento, obligando a la red a no depender de unidades concretas. Se desactiva en inferencia, con el escalado correspondiente.' },
  { id: 'fc-205', track: 'ai', module: 'a3', front: '¿Qué es SGD con momentum?', back: 'Acumula una media móvil exponencial de los gradientes para avanzar con más inercia. Suaviza oscilaciones y acelera la convergencia en valles estrechos.' },
  { id: 'fc-206', track: 'ai', module: 'a3', front: '¿Qué es Adam?', back: 'Optimizador que combina momentum con momentos de segundo orden al estilo de RMSProp y aplica corrección de sesgo. Es adaptativo y suele ser una buena elección por defecto.' },
  { id: 'fc-207', track: 'ai', module: 'a3', front: '¿Qué mejora AdamW sobre Adam con L2?', back: 'Separa el weight decay del término adaptativo: aplica el decaimiento directamente a los pesos en vez de sumarlo al gradiente. Da una regularización más correcta y suele rendir mejor.' },
  { id: 'fc-208', track: 'ai', module: 'a3', front: '¿Qué es un scheduling de learning rate?', back: 'Cambiar la tasa de aprendizaje durante el entrenamiento, normalmente con warmup inicial y decaimiento coseno o escalonado. Mejora estabilidad y resultado final.' },

  // ---------- LLMs (a4/a5) ----------
  { id: 'fc-209', track: 'ai', module: 'a4', front: '¿Qué es un token?', back: 'La unidad básica de texto que maneja el modelo: puede ser una subpalabra, un carácter o un símbolo especial. El modelo trabaja con sus IDs, no con letras.' },
  { id: 'fc-210', track: 'ai', module: 'a4', front: '¿Qué es BPE (Byte-Pair Encoding)?', back: 'Un algoritmo de tokenización que fusiona iterativamente los pares de símbolos más frecuentes. Equilibra un vocabulario manejable con secuencias cortas.', hint: 'Fusiona lo que más aparece' },
  { id: 'fc-211', track: 'ai', module: 'a4', front: '¿Por qué un LLM falla contando letras o dígitos?', back: 'Porque ve tokens, no caracteres. Una palabra como "strawberry" puede dividirse en varias piezas y un número grande en fragmentos, así que no tiene acceso directo a cada letra.' },
  { id: 'fc-212', track: 'ai', module: 'a4', front: '¿Qué es la ventana de contexto?', back: 'El número máximo de tokens que el modelo puede considerar en una llamada, contando entrada y salida. Si el prompt la supera hay que truncar, resumir o usar RAG.' },
  { id: 'fc-213', track: 'ai', module: 'a5', front: '¿Qué es la generación autorregresiva?', back: 'El modelo predice el token siguiente condicionado a todos los anteriores y lo añade a la secuencia, repitiendo hasta un token de fin o el límite de longitud.' },
  { id: 'fc-214', track: 'ai', module: 'a5', front: '¿Qué hace la temperatura en el sampling?', back: 'Divide los logits por T antes del softmax. T menor que 1 concentra la probabilidad en los tokens más probables; T mayor que 1 aplana la distribución y da más variedad.' },
  { id: 'fc-215', track: 'ai', module: 'a5', front: '¿Qué son top-k y top-p?', back: 'Top-k conserva solo los k tokens con mayor probabilidad; top-p conserva el conjunto mínimo cuya probabilidad acumulada supera p. Ambos recortan la cola de la distribución.', hint: 'Nucleus sampling es top-p' },
  { id: 'fc-216', track: 'ai', module: 'a5', front: '¿Qué es la KV cache?', back: 'Guardar en memoria las claves y los valores ya calculados por las capas de atención para cada token generado. Evita recalcular el prefijo en cada paso y acelera mucho la decodificación.', hint: 'Cambia cómputo por memoria' },
  { id: 'fc-217', track: 'ambos', module: 'ambos', front: '¿Qué es la cuantización de un LLM?', back: 'Representar pesos y a veces activaciones con menos bits, por ejemplo INT8 o INT4 en lugar de FP16. Reduce memoria y aumenta velocidad, con una posible pequeña pérdida de calidad.' },
  { id: 'fc-218', track: 'ai', module: 'a4', front: '¿Qué es el fine-tuning?', back: 'Continuar el entrenamiento de un modelo preentrenado con datos de una tarea o dominio concreto. Puede ser completo, actualizando todos los pesos, o eficiente en parámetros con LoRA.' },
  { id: 'fc-219', track: 'ai', module: 'a4', front: '¿Qué es LoRA?', back: 'Low-Rank Adaptation: congela los pesos originales y entrena dos matrices de bajo rango que se añaden a ciertas capas. Reduce drásticamente los parámetros entrenables y el coste.', hint: 'Delta de bajo rango sobre W' },
  { id: 'fc-220', track: 'ai', module: 'a4', front: '¿Qué es un embedding?', back: 'Un vector de baja dimensión que representa el significado de una palabra, frase o documento. Los textos semánticamente cercanos quedan cerca en el espacio y se comparan con similitud coseno.' },
  { id: 'fc-221', track: 'ai', module: 'a4', front: '¿Qué es RAG?', back: 'Retrieval-Augmented Generation: recuperar documentos relevantes con búsqueda vectorial o léxica y añadirlos al prompt para que el modelo responda apoyándose en evidencia externa y actualizada.', hint: 'Libro de referencia antes de contestar' },
  { id: 'fc-222', track: 'ai', module: 'a4', front: '¿Qué es una base de datos vectorial?', back: 'Un almacén que indexa embeddings para buscar los vectores más similares a una consulta. FAISS, Milvus, Weaviate y pgvector son opciones habituales.', hint: 'Busca por significado, no por palabra exacta' },
  { id: 'fc-223', track: 'ai', module: 'a4', front: '¿Qué es el chunking en RAG?', back: 'Dividir los documentos en fragmentos pequeños, normalmente con algo de solapamiento, antes de embedderlos. El tamaño del chunk afecta mucho a la precisión de la recuperación.' },
  { id: 'fc-224', track: 'ai', module: 'a4', front: '¿Qué es el reranking en RAG?', back: 'Reordenar los documentos recuperados con un modelo más preciso, normalmente un cross-encoder, antes de meterlos en el contexto. Mejora la calidad aunque añade latencia.' },
  { id: 'fc-225', track: 'ai', module: 'a4', front: '¿Qué es un agente LLM?', back: 'Un sistema donde el modelo decide qué herramientas usar, las ejecuta, observa los resultados y repite el ciclo hasta completar una tarea. El modelo aporta razonamiento; el código aporta acciones.' },
  { id: 'fc-226', track: 'ai', module: 'a4', front: '¿Qué es function calling?', back: 'El modelo emite una llamada estructurada a una función externa con argumentos en JSON. La aplicación ejecuta esa función y le devuelve el resultado para continuar.' },
  { id: 'fc-227', track: 'ai', module: 'a4', front: '¿Qué es el patrón ReAct?', back: 'Alternar razonamiento y acción: el modelo escribe un pensamiento, llama a una herramienta, recibe una observación y vuelve a razonar. Reduce errores y hace el proceso más interpretable.' },
  { id: 'fc-228', track: 'ai', module: 'a4', front: '¿Qué es MCP (Model Context Protocol)?', back: 'Un protocolo abierto que conecta modelos con herramientas y fuentes de datos mediante servidores MCP. Define tools, resources y prompts de forma estandarizada.', hint: 'USB-C para conectar modelos y datos' },
  { id: 'fc-229', track: 'ai', module: 'a4', front: '¿Qué riesgo introduce texto no confiable en el prompt?', back: 'Prompt injection: instrucciones ocultas en documentos o entradas que intentan anular las instrucciones del sistema. El contenido recuperado por RAG debe tratarse como datos, no como órdenes.' },
  { id: 'fc-230', track: 'ai', module: 'a4', front: '¿Qué es prompt engineering?', back: 'Diseñar las entradas al modelo con instrucciones claras, contexto, ejemplos y formato de salida explícito para mejorar el resultado sin modificar pesos.' },
  { id: 'fc-231', track: 'ai', module: 'a4', front: '¿Qué es few-shot prompting?', back: 'Incluir en el prompt un par de ejemplos de entrada y salida antes de la consulta real. Guía el formato y la tarea sin necesidad de entrenar.' },
  { id: 'fc-232', track: 'ai', module: 'a4', front: '¿Qué diferencia los mensajes system, user y assistant?', back: 'System fija rol y reglas, user aporta la petición y assistant son respuestas previas. El historial completo se concatena en cada llamada para condicionar la siguiente generación.' },

  // ---------- Serving y MLOps (a5/a6/a7) ----------
  { id: 'fc-233', track: 'ai', module: 'a5', front: '¿Qué es vLLM?', back: 'Un motor de inferencia para LLMs que usa PagedAttention para gestionar la KV cache en bloques. Mejora mucho el throughput respecto a un serving naive en GPU.', hint: 'Serving de alto rendimiento' },
  { id: 'fc-234', track: 'ai', module: 'a5', front: '¿Qué es PagedAttention?', back: 'Gestionar la caché de atención en bloques paginados, como la memoria virtual de un sistema operativo. Evita reservas contiguas grandes y el desperdicio cuando las secuencias tienen longitudes distintas.' },
  { id: 'fc-235', track: 'ai', module: 'a5', front: '¿Qué es continuous batching?', back: 'Insertar nuevas peticiones en el lote en cuanto una secuencia del lote termina, en vez de esperar a que acabe todo el batch. Aumenta el uso de GPU y el throughput.', hint: 'Se rellenan huecos en cada paso de decodificación' },
  { id: 'fc-236', track: 'ai', module: 'a5', front: '¿Qué son TTFT y TPOT?', back: 'TTFT es el tiempo hasta el primer token, dominado por el prefill del prompt. TPOT es el tiempo medio entre tokens durante la decodificación; afecta a la fluidez percibida.' },
  { id: 'fc-237', track: 'ai', module: 'a5', front: '¿Qué es el throughput en inferencia?', back: 'Cantidad de tokens o peticiones procesadas por segundo. Sube con batching y cuantización, pero suele tensionar la latencia por token o el coste por petición.' },
  { id: 'fc-238', track: 'ai', module: 'a6', front: '¿Qué es data drift?', back: 'Cambio en la distribución de los datos de entrada respecto a los usados al entrenar. El modelo se degrada aunque el código no haya cambiado.', hint: 'La entrada ya no parece la de antes' },
  { id: 'fc-239', track: 'ai', module: 'a6', front: '¿Qué es concept drift?', back: 'Cambio en la relación entre entrada y salida: lo que significa "positivo" ya no es lo mismo. Es más grave que el data drift porque el propio objetivo se ha movido.' },
  { id: 'fc-240', track: 'ai', module: 'a6', front: '¿Qué son los evals de un sistema con LLM?', back: 'Conjuntos de casos con criterios claros que miden calidad: corrección, formato, seguridad, tono. Son los tests del comportamiento del modelo.', hint: 'Tests unitarios para IA' },
  { id: 'fc-241', track: 'ai', module: 'a6', front: '¿Qué es un eval de regresión?', back: 'Volver a ejecutar el mismo conjunto de evaluaciones tras cada cambio para detectar que una mejora ha roto casos que antes funcionaban.' },
  { id: 'fc-242', track: 'ai', module: 'a6', front: '¿Qué es LLM-as-a-judge?', back: 'Usar otro modelo para puntuar respuestas según una rúbrica. Escala bien, pero tiene sesgos propios; conviene validarlo contra juicios humanos.', hint: 'Un modelo calificando a otro' },
  { id: 'fc-243', track: 'ai', module: 'a6', front: '¿Qué es un A/B test con modelo?', back: 'Exponer dos versiones del sistema a grupos de usuarios y comparar métricas de negocio reales. Complementa las evaluaciones offline, que nunca capturan todo el comportamiento.', hint: 'La verdad está en producción' },
  { id: 'fc-244', track: 'ai', module: 'a6', front: '¿Qué es el shadow mode?', back: 'Desplegar el modelo nuevo en paralelo sin que sus respuestas lleguen a los usuarios, y compararlas con las del sistema actual. Permite validar antes de cortar el tráfico.' },
  { id: 'fc-245', track: 'ai', module: 'a7', front: '¿Qué significa CI/CD/CT en MLOps?', back: 'Integración y entrega continuas del código, más entrenamiento continuo del modelo. Automatiza tests, validación de datos, reentrenamiento, registro y despliegue.' },
  { id: 'fc-246', track: 'ai', module: 'a7', front: '¿Qué es un feature store?', back: 'Un repositorio central de features que garantiza que se calculan igual en entrenamiento y en inferencia. Reduce el training-serving skew y facilita reutilización.' },
  { id: 'fc-247', track: 'ai', module: 'a7', front: '¿Qué es training-serving skew?', back: 'La diferencia entre cómo se generan las features al entrenar y cómo se generan al servir. Produce una caída de rendimiento en producción que los evals offline no veían.' },
  { id: 'fc-248', track: 'ai', module: 'a7', front: '¿Qué incluye la observabilidad de un sistema de ML?', back: 'Métricas de servicio (latencia, errores, uso), trazas, logs y monitorización de entradas, salidas y deriva. Permite detectar degradación antes de que afecte al negocio.' },
  { id: 'fc-249', track: 'ai', module: 'a7', front: '¿Qué es un despliegue canary?', back: 'Liberar la versión nueva solo para un pequeño porcentaje del tráfico y ampliarla gradualmente si las métricas se mantienen. Limita el impacto de un fallo.' },
  { id: 'fc-250', track: 'ai', module: 'a7', front: '¿Qué se registra para poder reproducir un experimento?', back: 'Versión del código, del dataset, hiperparámetros, semilla, métricas y artefactos del modelo. Herramientas como MLflow o DVC lo rastrean para auditoría y repetibilidad.', hint: 'Si no está registrado, no es reproducible' },

  // ---------- T3 Code (a11) ----------
  { id: 'fc-251', track: 'ai', module: 'a11', front: `¿Qué es T3 Code?`, back: `Un asistente de programación basado en agentes que ejecuta tareas de ingeniería de software reales: lee y edita archivos, corre comandos, ejecuta tests y puede abrir PRs. No se limita a sugerir texto en el chat: actúa sobre un entorno de trabajo.`, hint: `Agente que trabaja en el repositorio` },
  { id: 'fc-252', track: 'ai', module: 'a11', front: `¿Qué es el control plane en T3 Code?`, back: `La capa central que coordina la sesión: recibe la instrucción, decide qué agente o herramienta actúa en cada paso, gestiona permisos, checkpoints y el estado de la tarea. Separa la decisión de la ejecución, que ocurre en el entorno local.`, hint: `El cerebro que dirige, no el que escribe el código` },
  { id: 'fc-253', track: 'ai', module: 'a11', front: `¿Qué son los proveedores (providers) en T3 Code?`, back: `Adaptadores que conectan el control plane con distintos modelos o backends de inferencia. Permiten cambiar de modelo o de servicio sin alterar el flujo de trabajo ni las herramientas del agente.` },
  { id: 'fc-254', track: 'ai', module: 'a11', front: `¿Qué es un worktree en T3 Code?`, back: `Una copia aislada del repositorio creada con git worktree, donde el agente trabaja en una rama propia sin ensuciar tu directorio principal. Permite que varias tareas avancen en paralelo sobre la misma base.`, hint: `Un checkout separado por tarea` },
  { id: 'fc-255', track: 'ai', module: 'a11', front: `¿Para qué sirve trabajar en un worktree?`, back: `Aísla los cambios: puedes revisar el diff del agente antes de integrarlos, descartar la rama si el resultado no sirve y evitar conflictos con tu trabajo actual. Cada tarea tiene su propio espacio de trabajo.` },
  { id: 'fc-256', track: 'ai', module: 'a11', front: `¿Qué es un thread en T3 Code?`, back: `Una conversación o sesión de trabajo continua con su propio historial y contexto: mensajes, razonamientos y acciones se agrupan en hilos que puedes retomar más adelante. Varios threads pueden ejecutarse a la vez.`, hint: `La conversación, no el disco` },
  { id: 'fc-257', track: 'ai', module: 'a11', front: `¿Qué diferencia un thread de un worktree?`, back: `El thread es la conversación y el razonamiento del agente; el worktree es el espacio físico en disco donde se aplican los cambios. Normalmente un hilo se asocia a un worktree concreto.` },
  { id: 'fc-258', track: 'ai', module: 'a11', front: `¿Qué son los modos de permiso en T3 Code?`, back: `Niveles de autonomía que deciden qué acciones puede realizar el agente sin preguntar: desde solo lectura o sugerencias, pasando por confirmación por acción, hasta aprobación automática de ediciones y comandos.`, hint: `Cuánta autonomía se le da` },
  { id: 'fc-259', track: 'ai', module: 'a11', front: `¿Por qué importan los modos de permiso?`, back: `Equilibran velocidad y seguridad: limitan operaciones destructivas como borrar archivos, hacer push o ejecutar scripts, y exigen revisión humana en los puntos delicados del flujo.` },
  { id: 'fc-260', track: 'ai', module: 'a11', front: `¿Qué es un checkpoint en T3 Code?`, back: `Un punto de guardado del estado de la tarea, con sus cambios y su progreso, al que puedes volver. Permite revertir un paso del agente o comparar versiones sin perder el trabajo anterior.`, hint: `Como un commit temporal de la sesión` },
  { id: 'fc-261', track: 'ai', module: 'a11', front: `¿Para qué sirve un checkpoint antes de pedir un cambio grande?`, back: `Para poder experimentar con seguridad: si el resultado empeora, restauras el estado anterior y pruebas otro enfoque sin haber destruido lo que ya funcionaba.` },
  { id: 'fc-262', track: 'ai', module: 'a11', front: `¿Qué es el diff en T3 Code?`, back: `La lista de cambios exactos que el agente propone: archivos tocados y líneas añadidas o borradas. Es la herramienta principal para revisar qué hizo antes de aceptar su trabajo.`, hint: `La verdad del código, no el resumen` },
  { id: 'fc-263', track: 'ai', module: 'a11', front: `¿Por qué revisar el diff y no solo el mensaje del agente?`, back: `Porque el resumen puede ser optimista o incompleto. El diff muestra la realidad: cambios no intencionados, archivos que no debían tocarse o soluciones que no coinciden con lo pedido.` },
  { id: 'fc-264', track: 'ai', module: 'a11', front: `¿Qué es una PR en el flujo de T3 Code?`, back: `Un pull request: el agente puede crear una rama, commitear sus cambios y abrir la PR para integración, con título y descripción derivados de la tarea, dejando el trabajo listo para revisión.`, hint: `Pull request` },
  { id: 'fc-265', track: 'ai', module: 'a11', front: `¿Qué ventaja tiene que el agente abra la PR?`, back: `Cierra el ciclo de entrega: deja el trabajo con diff y contexto listo para la revisión humana y la integración continua, en lugar de cambios sueltos en local. Aporta trazabilidad.` },
  { id: 'fc-266', track: 'ai', module: 'a11', front: `¿Qué significa trabajar con un remoto en T3 Code?`, back: `Que el agente interactúa con el repositorio remoto (GitHub, GitLab…): hacer fetch, push, abrir PRs o leer issues, siempre según los permisos que se le hayan concedido.` },
  { id: 'fc-267', track: 'ai', module: 'a11', front: `¿Qué riesgo tiene dar acceso al remoto al agente?`, back: `Puede escribir en ramas compartidas o abrir PRs no deseados. Conviene limitar los permisos de push y exigir revisión humana antes de publicar cualquier cambio.`, hint: `Lo que sube, otros lo ven` },
  { id: 'fc-268', track: 'ai', module: 'a11', front: `¿Qué es una policy en T3 Code?`, back: `Un conjunto de reglas que restringen qué puede hacer el agente: comandos permitidos o prohibidos, archivos sensibles, límites de gasto y pasos que requieren aprobación explícita.` },
  { id: 'fc-269', track: 'ai', module: 'a11', front: `¿Qué diferencia una policy de un modo de permiso?`, back: `El modo de permiso fija el nivel general de autonomía de la sesión; la policy son reglas concretas y granulares que pueden bloquear acciones específicas aunque el modo sea permisivo.`, hint: `General vs. específico` },
  { id: 'fc-270', track: 'ai', module: 'a11', front: `¿Qué son los límites (limits) en T3 Code?`, back: `Topes configurables de la sesión: tokens, coste, tiempo, número de pasos o de iteraciones del agente. Evitan ejecuciones desbocadas y facturas inesperadas.`, hint: `El cortocircuito de la sesión` },
  { id: 'fc-271', track: 'ai', module: 'a11', front: `¿Por qué configurar límites de coste y de pasos?`, back: `Porque un agente en bucle puede consumir muchos tokens o repetir la misma acción indefinidamente. Los límites cortan la ejecución y obligan a revisar el enfoque antes de seguir gastando.` },
  { id: 'fc-272', track: 'ai', module: 'a11', front: `¿Qué es el plan de ejecución de T3 Code?`, back: `La secuencia de pasos que el agente propone antes de actuar: qué archivos tocar, qué comandos ejecutar y en qué orden. Permite corregir el rumbo antes de que modifique nada.` },
  { id: 'fc-273', track: 'ai', module: 'a11', front: `¿Qué hace el modo de solo lectura (read-only)?`, back: `El agente puede explorar el repositorio, leer archivos y razonar, pero no editar ni ejecutar acciones con efectos. Es útil para análisis y para auditar sus propuestas sin riesgo.` },
  { id: 'fc-274', track: 'ai', module: 'a11', front: `¿Qué es el modo de planificación (plan mode)?`, back: `El agente investiga y propone un plan sin aplicar cambios; hasta que lo apruebas, no escribe en el worktree. Reduce el riesgo de que empiece a editar con un enfoque equivocado.`, hint: `Pensar antes de tocar el código` },
  { id: 'fc-275', track: 'ai', module: 'a11', front: `¿Cómo se integra T3 Code con git internamente?`, back: `Apoyándose en worktrees, ramas y commits: cada tarea aísla su estado en un checkout propio y la entrega se realiza mediante un diff y una PR sobre la rama base.` },
  { id: 'fc-276', track: 'ai', module: 'a11', front: `¿Qué debe incluir la instrucción inicial para T3 Code?`, back: `Objetivo concreto, criterios de aceptación, archivos o módulos implicados, restricciones y cómo se verificará el resultado. Cuanto más preciso sea el encargo, menos iteraciones harán falta.`, hint: `Un buen brief evita malentendidos` },
  { id: 'fc-277', track: 'ai', module: 'a11', front: `¿Qué significa "human in the loop" en T3 Code?`, back: `Mantener la revisión humana en los puntos clave: aprobar el plan, revisar el diff y decidir sobre la PR. El agente ejecuta las tareas; la persona valida y da el visto bueno.` },
  { id: 'fc-278', track: 'ai', module: 'a11', front: `¿Qué señal indica que hay que detener al agente e intervenir?`, back: `Que repite la misma acción sin avanzar, que toca archivos fuera de alcance o que el diff crece sin relación con la tarea. Es el momento de revisar permisos o reformular el prompt.`, hint: `Repetición sin progreso` },
  { id: 'fc-279', track: 'ai', module: 'a11', front: `¿Cómo se relacionan checkpoint y worktree al revertir?`, back: `El checkpoint restaura el estado dentro de la sesión actual; el worktree permite ir más lejos y descartar toda la rama de trabajo si la tarea se abandona por completo.`, hint: `Undo de sesión vs. descarte de rama` },
  { id: 'fc-280', track: 'ai', module: 'a11', front: `¿Qué es la trazabilidad en T3 Code?`, back: `El registro de qué comandos, acciones y decisiones tomó el agente en cada thread. Permite revisar después por qué se hizo un cambio y ayuda a cumplir políticas de seguridad y auditoría.` },

  // ---------- Orquestación de agentes (a12) ----------
  { id: 'fc-281', track: 'ai', module: 'a12', front: `¿Qué es la orquestación de agentes?`, back: `Coordinar varios agentes o ejecuciones para resolver una tarea compleja: repartir subtareas, ejecutarlas, recoger los resultados y combinarlos con puntos de supervisión y verificación.`, hint: `Un equipo, no un agente solitario` },
  { id: 'fc-282', track: 'ai', module: 'a12', front: `¿Cuál es la principal ventaja del paralelismo de agentes?`, back: `Reducir el tiempo total haciendo tareas independientes a la vez: investigación, implementación y tests pueden avanzar simultáneamente, cada uno en su propio worktree.`, hint: `Menos tiempo de reloj` },
  { id: 'fc-283', track: 'ai', module: 'a12', front: `¿Qué requisito deben cumplir las tareas para paralelizarlas?`, back: `Ser independientes y tener interfaces claras: qué entrada consume y qué salida produce. Si comparten estado o se solapan en los mismos archivos, el paralelismo genera conflictos.`, hint: `Sin dependencias, sin solapamientos` },
  { id: 'fc-284', track: 'ai', module: 'a12', front: `¿Qué es un agente revisor (reviewer)?`, back: `Un agente distinto del que implementa, encargado de examinar el código o la solución buscando errores, casos límite y desviaciones del requisito, sin el sesgo de quien la escribió.`, hint: `Segunda mirada independiente` },
  { id: 'fc-285', track: 'ai', module: 'a12', front: `¿Por qué separar implementador y revisor?`, back: `Porque el mismo modelo tiende a confirmar su propio enfoque por anclaje. Un revisor con contexto fresco y criterios distintos detecta fallos que el autor pasa por alto.`, hint: `Quien escribió, no siempre encuentra el error` },
  { id: 'fc-286', track: 'ai', module: 'a12', front: `¿Cómo se divide una tarea grande entre agentes?`, back: `Descomponiéndola en subtareas con límites concretos: módulo o archivos a tocar, criterio de éxito y formato de salida. Así cada agente puede trabajar sin depender de los demás.`, hint: `Subtareas con fronteras claras` },
  { id: 'fc-287', track: 'ai', module: 'a12', front: `¿Qué debe contener un buen prompt de delegación?`, back: `Objetivo, contexto mínimo necesario, restricciones, herramientas disponibles, formato de respuesta y criterio de verificación. Evita ambigüedades y suposiciones del agente.`, hint: `Encargo, límites y prueba de éxito` },
  { id: 'fc-288', track: 'ai', module: 'a12', front: `¿Qué es el patrón fan-out / fan-in?`, back: `Repartir una tarea en muchas ramas paralelas (fan-out) y luego reunir y sintetizar los resultados en una sola salida (fan-in), con un agente que integra y valida el conjunto.`, hint: `Separar para trabajar, juntar para entregar` },
  { id: 'fc-289', track: 'ai', module: 'a12', front: `¿Cuándo NO conviene usar orquestación multiagente?`, back: `Cuando la tarea es pequeña, está muy acoplada o exige mucho contexto compartido: la sobrecarga de coordinación y los conflictos salen más caros que resolverla con un solo agente.`, hint: `Más agentes no siempre es mejor` },
  { id: 'fc-290', track: 'ai', module: 'a12', front: `¿Qué otro escenario desaconseja paralelizar agentes?`, back: `Cuando no existe una forma objetiva de verificar o combinar los resultados, o cuando el coste y los límites de tokens se disparan sin una ganancia clara de calidad.`, hint: `Si no se puede juzgar el resultado, no lo repartas` },
  { id: 'fc-291', track: 'ai', module: 'a12', front: `¿Qué riesgo aparece al agregar varios agentes?`, back: `Que los errores se amplifiquen y se propaguen: si un agente introduce una suposición equivocada, los demás pueden construir sobre ella. Por eso hacen falta checkpoints y verificación.`, hint: `Un fallo se multiplica por el número de agentes` },
  { id: 'fc-292', track: 'ai', module: 'a12', front: `¿Qué métrica decide si la orquestación vale la pena?`, back: `El tiempo hasta obtener un resultado correcto y el coste total, comparados con los de un único agente. Si paralelizar no mejora ambos, la complejidad añadida no se justifica.`, hint: `Compara contra la línea base de un agente` },

  // ---------- Método Jensen Huang (a12) ----------
  { id: 'fc-293', track: 'ai', module: 'a12', front: `¿Qué es el método Jensen Huang para trabajar con IA?`, back: `Un enfoque de uso avanzado que trata a la IA como un colaborador al que hay que saber preguntar: primero mejorar la pregunta, contrastar con fuentes y otra IA, y mantener siempre el criterio humano.`, hint: `Preguntar mejor, verificar, decidir uno mismo` },
  { id: 'fc-294', track: 'ai', module: 'a12', front: `¿Qué significa "preguntar cómo preguntar"?`, back: `Pedir al modelo que te ayude a formular mejor la pregunta antes de dar la respuesta: que identifique supuestos, ambigüedades y datos que faltan. Suele mejorar más el resultado que iterar a ciegas.`, hint: `La meta-pregunta` },
  { id: 'fc-295', track: 'ai', module: 'a12', front: `¿Por qué funciona pedir una mejor versión de tu pregunta?`, back: `Porque el modelo puede exponer los vacíos de contexto que un humano da por supuestos y conoce la forma en que interpreta las instrucciones. La respuesta nunca supera el límite del prompt.`, hint: `Basura entra, basura sale` },
  { id: 'fc-296', track: 'ai', module: 'a12', front: `¿Qué es el bucle recursivo de preguntas del método Huang?`, back: `Repetir el ciclo: preguntar, pedir una versión mejor de la pregunta, volver a preguntar con esa versión y así sucesivamente, hasta que la pregunta sea precisa y la respuesta verificable.`, hint: `Mejorar la pregunta antes que la respuesta` },
  { id: 'fc-297', track: 'ai', module: 'a12', front: `¿Qué es la "segunda IA" en el método Huang?`, back: `Usar un modelo distinto, o una sesión independiente, para revisar la respuesta del primero: contrastar, buscar errores y aportar una perspectiva que no comparte el mismo razonamiento.`, hint: `Una opinión fuera de la caja` },
  { id: 'fc-298', track: 'ai', module: 'a12', front: `¿Por qué usar una segunda IA y no la misma?`, back: `Porque el mismo modelo tiende a repetir sus sesgos y a confirmar su primera respuesta. Otro modelo, con otro entrenamiento, aporta divergencia y detecta fallos distintos.`, hint: `Dos cabezas piensan mejor que una` },
  { id: 'fc-299', track: 'ai', module: 'a12', front: `¿Qué es la fuente primaria en este método?`, back: `El documento, dato o código original contra el que se contrasta lo que afirma la IA: papers, documentación oficial, repositorios o mediciones reales. La IA es un atajo, no la verdad.`, hint: `Ir al documento original` },
  { id: 'fc-300', track: 'ai', module: 'a12', front: `¿Por qué priorizar la fuente primaria sobre la respuesta de la IA?`, back: `Porque el modelo puede alucinar o parafrasear mal. Acudir a la fuente permite verificar afirmaciones, citar correctamente y descubrir cuándo la IA inventó un detalle con total seguridad.`, hint: `La fluidez no garantiza exactitud` },
  { id: 'fc-301', track: 'ai', module: 'a12', front: `¿Qué significa "controlabilidad" en el método Huang?`, back: `La capacidad de dirigir y limitar al modelo: instrucciones precisas, formato acotado, restricciones explícitas y decisión humana sobre cuándo parar. El humano lleva el volante.`, hint: `Tú mandas, la IA ejecuta` },
  { id: 'fc-302', track: 'ai', module: 'a12', front: `¿Cómo se aumenta la controlabilidad de un prompting?`, back: `Definiendo rol, contexto, ejemplos, formato de salida, restricciones claras y criterios de aceptación. Cuanto más estructurado el encargo, menos espacio queda para divagaciones.`, hint: `Especificar para no improvisar` },
  { id: 'fc-303', track: 'ai', module: 'a12', front: `¿Qué exige "definir mejor antes" en el método Huang?`, back: `Acordar explícitamente qué significa mejor —qué métrica, criterio o propósito— antes de pedir una mejora. Sin esa definición, el modelo optimiza algo distinto de lo que quieres.`, hint: `No puedes mejorar lo que no defines` },
  { id: 'fc-304', track: 'ai', module: 'a12', front: `¿Qué pasa si no defines qué significa "mejor"?`, back: `Que la IA produce cambios que suenan bien pero no resuelven el problema real: optimiza estilo, longitud o apariencia en lugar del objetivo. Hay que medir contra un criterio concreto.`, hint: `Resultado bonito, problema sin resolver` },
  { id: 'fc-305', track: 'ai', module: 'a12', front: `¿Qué es la verificación en el método Huang?`, back: `Comprobar la salida con evidencia externa antes de aceptarla: ejecutar el código, contrastar con documentación, pedir una segunda opinión y validar con tests o datos reales.`, hint: `Confiar pero comprobar` },
  { id: 'fc-306', track: 'ai', module: 'a12', front: `¿Qué checklist mínima de verificación recomienda el método?`, back: `Cuatro preguntas: ¿responde a la pregunta?, ¿está respaldada por una fuente primaria?, ¿la confirmó otra IA o una prueba?, y ¿cumple el criterio de mejor que definimos antes?`, hint: `Pregunta, fuente, contraste, criterio` },
  { id: 'fc-307', track: 'ai', module: 'a12', front: `¿Qué son las métricas antes/después en este método?`, back: `Registrar el estado inicial —calidad, tiempo, errores— y el final tras aplicar la IA, para saber si hubo mejora real y cuánta. Sin línea base no se puede afirmar que algo mejoró.`, hint: `Necesitas un punto de partida` },
  { id: 'fc-308', track: 'ai', module: 'a12', front: `¿Cuál es el anti-patrón de aceptar la primera respuesta?`, back: `Tomar la salida inicial como correcta sin cuestionarla ni verificarla. Es el error más frecuente: confundir fluidez y tono seguro con exactitud.`, hint: `La primera respuesta es un borrador` },
  { id: 'fc-309', track: 'ai', module: 'a12', front: `¿Qué anti-patrones identifica el método Huang?`, back: `Aceptar la primera respuesta sin verificar, no definir el objetivo, no contrastar fuentes primarias, delegar el juicio crítico al modelo y reformular igual tras un mal resultado.`, hint: `Automaticidad, vaguedad y pereza crítica` },
  { id: 'fc-310', track: 'ai', module: 'a12', front: `¿Cómo se cierra el ciclo del método Huang?`, back: `Reformulando la pregunta, verificando con fuentes y segunda IA, midiendo contra el criterio definido y decidiendo con criterio humano si se acepta el resultado o se itera una vez más.`, hint: `Preguntar, contrastar, medir, decidir` },
];
